package io.github.diodeme.ji.resource.local;

import io.github.diodeme.ji.extension.PromptContributor;
import io.github.diodeme.ji.extension.ResourceDescriptor;
import io.github.diodeme.ji.extension.ResourcePromptContributor;
import io.github.diodeme.ji.extension.ResourceSource;
import java.nio.charset.StandardCharsets;
import java.util.Comparator;
import java.util.List;

/** Projects one trusted catalog snapshot into prompt contributors without owning resource state. */
public final class ResourcePromptContributors {
    private ResourcePromptContributors() {}

    public static List<PromptContributor> contexts(ResourceCatalog.Snapshot snapshot, int priority, int tokenBudget) {
        return snapshot.ready().stream()
                .filter(item -> item.descriptor().kind() == ResourceDescriptor.ResourceKind.CONTEXT)
                .sorted(Comparator.comparing(item -> item.descriptor().id().value()))
                .map(item -> contributor(item, priority, tokenBudget))
                .map(PromptContributor.class::cast)
                .toList();
    }

    private static ResourcePromptContributor contributor(ResourceCatalog.Item item, int priority, int tokenBudget) {
        var loaded = new ResourceSource.LoadedResource(item.descriptor(), item.content(), StandardCharsets.UTF_8);
        return new ResourcePromptContributor("resource:" + item.descriptor().id().value(), loaded, priority, tokenBudget);
    }
}
